			function getDongAddr(jusoJibeon) {
			    if (jusoJibeon == null || jusoJibeon == "") {
			        return "";
			    }
			    var arr = [
			        "도", "도시", "도시동", "도시면리", "도시읍리", "도시구동",
			        "도군", "도군읍", "도군읍리", "도군면", "도군면리", 
			        "시구", "시구가", "시구동",
			        "시군", "시군면리", "시군읍리",
			        "시동", "시읍리", "시면리"
			        ];
			    var arr2 = [
			        "도시가", "도시동", "도시면리", "도시읍리", "도시구동", "도시구가",
			        "도군읍리", "도군읍가", "도군면리", "도군면가", 
			        "시구가", "시구동",
			        "시군면리", "시군읍리", "시군면가", "시군읍가",
			        "시동", "시읍리", "시면리", "시가", "시읍가", "시면가"
			        ];
			    
			    var tmpArr = jusoJibeon.split(" ");
			    var str = "";
			    var str2 = "";
			    for (var i=0; i < tmpArr.length; i++) {
			        str += tmpArr[i].substr(-1);
			        str2 = str2 + " " + tmpArr[i];
			        for (var j=0; j < arr2.length; j++) {
			            if (str == arr2[j]) {
			                return str2.substr(1);
			            }
			        }
			    }
			    return "";
			}

